/** @param {{des: object}} api */
export default function fakewiz2({ des, selection, hell_tweaks }) {
    des.level_init({ style: 'mazegrid', bg: '-' });

    des.level_flags('mazelevel');

    const tmpbounds = selection.match('-');
    const bnds = selection.bounds(tmpbounds);
    const bounds2 = selection.fillrect(bnds.lx, bnds.ly + 1, bnds.hx - 2, bnds.hy - 1);

    const fakewiz2 = des.map({
        halign: 'center', valign: 'center', map: `.........
.}}}}}}}.
.}}---}}.
.}--.--}.
.}|...|}.
.}--.--}.
.}}---}}.
.}}}}}}}.
.........
`,
        contents: (rm) => {
            des.levregion(
                { region: [1, 0, 79, 20], region_islev: 1, exclude: [0, 0, 8, 8], type: 'stair-up' }
            );
            des.levregion(
                { region: [1, 0, 79, 20], region_islev: 1, exclude: [0, 0, 8, 8], type: 'stair-down' }
            );
            des.levregion(
                { region: [1, 0, 79, 20], region_islev: 1, exclude: [0, 0, 8, 8], type: 'branch' }
            );
            des.teleport_region({ region: [1, 0, 79, 20], region_islev: 1, exclude: [2, 2, 6, 6] });
            des.mazewalk(8, 5, 'east');
            des.monster('L', 4, 4);
            des.monster('vampire lord', 3, 4);
            des.monster('kraken', 6, 6);
            // And to make things a little harder.
            des.trap('board', 4, 3);
            des.trap('board', 4, 5);
            des.trap('board', 3, 4);
            des.trap('board', 5, 4);
            // treasures
            des.object('"', 4, 4);
        },
    });

    const protected_ = selection.bor(selection.negate(bounds2), fakewiz2);
    hell_tweaks(protected_);
}
